"""Generated by A2C: every declared setting is read; missing required ones are named."""
import pytest

from reconciliation_service.settings import MissingSettings, load_settings


def test_all_settings_are_read():
    assert set(load_settings({'TABLE_NAME': 'x', 'SETTLEMENT_API_URL': 'http://settlement-service.internal:8080', 'RECON_TENANT': 'acme'})) == {'RECON_TENANT', 'TABLE_NAME', 'SETTLEMENT_API_URL'}


def test_missing_required_settings_are_named():
    required = ['TABLE_NAME']
    if not required:
        return
    with pytest.raises(MissingSettings) as error:
        load_settings({})
    assert all(name in str(error.value) for name in required)
